import numpy as np
from scipy import ndimage
A=np.load('source_pixels.npz')['rgb']
conds={
'yellow':lambda x:(x[...,0]>100)&(x[...,1]>90)&(x[...,1]>x[...,2]*1.4)&(x[...,0]>x[...,2]*1.4),
'green':lambda x:(x[...,1]>80)&(x[...,1]>x[...,0]*1.15)&(x[...,1]>x[...,2]*1.15),
'bright':lambda x:x.mean(2)>160,
}
for name,fn in conds.items():
 print('\\n',name)
 for t in range(96):
  m=fn(A[t]); lab,n=ndimage.label(m)
  cc=[]
  for i in range(1,n+1):
   ys,xs=np.where(lab==i); s=len(xs)
   if s>=2: cc.append((s,round(xs.mean(),1),round(ys.mean(),1),int(xs.min()),int(ys.min()),int(xs.max()),int(ys.max())))
  cc=sorted(cc,reverse=True)[:5]
  if t%4==0 or (cc and cc[0][0]>10): print(t,cc)
